tool_input_args.value:
json; conn = sqlite3.connect('/workspace/world.db'); conn.row_factory = sqlite3.Row; cursor = conn.cursor(); tables = [r[0] for r in cursor.execute('SELECT name FROM sqlite_master WHERE type=\"table\"').fetchall()]; result = {}; 
for t in tables:
    cols = [r[1] for r in cursor.execute(f'PRAGMA table_info({t})').fetchall()]
    count = cursor.execute(f'SELECT COUNT(*) FROM {t}').fetchone()[0]
    result[t] = {'columns': cols, 'count': count}
print(json.dumps(result, indent=2)); conn.close()\

